(self.webpackChunkdemo=self.webpackChunkdemo||[]).push([[63325],{63325:n=>{n.exports="import {NgForOf} from '@angular/common';\nimport {Component, inject} from '@angular/core';\nimport {changeDetection} from '@demo/emulate/change-detection';\nimport {encapsulation} from '@demo/emulate/encapsulation';\nimport {TuiTabBar} from '@taiga-ui/addon-mobile';\nimport {TuiAlertService} from '@taiga-ui/core';\n\ninterface Item {\n    badge?: number;\n    icon: string;\n    text: string;\n}\n\n@Component({\n    standalone: true,\n    exportAs: \"Example7\",\n    selector: 'tui-tab-bar-example-liquid-android',\n    imports: [NgForOf, TuiTabBar],\n    templateUrl: './index.html',\n    styleUrls: ['./index.less'],\n    encapsulation,\n    changeDetection,\n    host: {\n        '[attr.data-platform]': '\"android\"',\n        '[class.tui-liquid-glass]': 'true',\n    },\n})\nexport default class Example {\n    private readonly alerts = inject(TuiAlertService);\n\n    protected activeItemIndex = 1;\n\n    protected readonly items: Item[] = [\n        {\n            text: 'Favorites',\n            icon: '@tui.heart',\n            badge: 3,\n        },\n        {\n            text: 'Calls',\n            icon: '@tui.phone',\n            badge: 1234,\n        },\n        {\n            text: 'Profile',\n            icon: '@tui.user',\n        },\n    ];\n\n    protected onIndexChange(index: number): void {\n        const item = this.items[index];\n\n        this.activeItemIndex = index;\n\n        if (item) {\n            item.badge = 0;\n            this.alerts.open(index, {label: item.text}).subscribe();\n        }\n    }\n}\n"}}]);